<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Когда исполнитель освобождается от неустойки по госконтракту?", "acceptedAnswer": {"@type": "Answer", "text": "Когда докажет, что неисполнение или ненадлежащее исполнение произошло вследствие непреодолимой силы или по вине заказчика — часть 9 статьи 34 закона № 44-ФЗ. Бремя доказывания лежит на нарушившей стороне."}}, {"@type": "Question", "name": "Что считается виной заказчика?", "acceptedAnswer": {"@type": "Answer", "text": "Непереданная площадка или документация, неперечисленный аванс, затянутые согласования, изменения задания без сдвига сроков, уклонение от приёмки — встречные неисполнения, из-за которых исполнитель объективно не мог уложиться в срок."}}, {"@type": "Question", "name": "Начисляется ли неустойка, пока заказчик не передал площадку?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. По пункту 3 статьи 405 ГК должник не считается просрочившим, пока обязательство не может быть исполнено вследствие просрочки кредитора: дни ожидания площадки, документации или аванса исключаются из расчёта."}}, {"@type": "Question", "name": "Является ли срыв поставки поставщиком форс-мажором?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Пункт 3 статьи 401 ГК прямо исключает из непреодолимой силы нарушение обязанностей контрагентами, отсутствие на рынке товаров и отсутствие денег — это предпринимательские риски исполнителя."}}, {"@type": "Question", "name": "Чем подтверждать форс-мажор?", "acceptedAnswer": {"@type": "Answer", "text": "Заключением или сертификатом торгово-промышленной палаты, актами органов власти, справками уполномоченных служб — плюс доказательством уведомления заказчика в срок, установленный контрактом."}}, {"@type": "Question", "name": "Что делать, если виноваты обе стороны?", "acceptedAnswer": {"@type": "Answer", "text": "Работает статья 404 ГК: суд соответственно уменьшает ответственность должника при вине обеих сторон, а также если кредитор содействовал увеличению убытков. Доля вины заказчика конвертируется в снижение суммы."}}, {"@type": "Question", "name": "Как снизить несоразмерную неустойку?", "acceptedAnswer": {"@type": "Answer", "text": "Заявить о применении статьи 333 ГК письменно в суде первой инстанции. Для предпринимателей снижение договорной неустойки допускается в исключительных случаях — когда взыскание полной суммы даст кредитору необоснованную выгоду."}}, {"@type": "Question", "name": "Может ли заказчик удержать спорную неустойку из оплаты?", "acceptedAnswer": {"@type": "Answer", "text": "Заказчики практикуют зачёт и удержание из обеспечения, но зачёт спорного, не подтверждённого требования уязвим. Фиксируйте спор письменными возражениями сразу — и требуйте возврата неосновательно удержанного."}}, {"@type": "Question", "name": "Чем освобождение отличается от списания по постановлению № 783?", "acceptedAnswer": {"@type": "Answer", "text": "Освобождение — спор о правомерности начисления. Списание — прощение подтверждённого долга при исполненном контракте: до 5 % цены полностью, от 5 до 20 % наполовину. Подтверждение долга ради списания ломает позицию об освобождении."}}, {"@type": "Question", "name": "Можно ли оплатить неустойку с лицевого счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Неустойка — не расход на исполнение контракта, кода направления расходования под неё нет. Источник — собственные средства с расчётного счёта; в раздельном учёте санкции отражаются вне себестоимости контракта."}}, {"@type": "Question", "name": "Освобождает ли непреодолимая сила от исполнения контракта?", "acceptedAnswer": {"@type": "Answer", "text": "Нет, только от ответственности за период её действия. Когда обстоятельства отпали, обязательство исполняется дальше; при длительной невозможности стороны решают вопрос об изменении или расторжении контракта."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Что делать, если заказчик требует неустойку по госконтракту", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Проверьте расчёт", "text": "Пеня — 1/300 ключевой ставки от цены, уменьшенной на стоимость исполненного; штрафы — по правилам контракта. Ошибки в базе и периоде встречаются в половине претензий."}, {"@type": "HowToStep", "position": 2, "name": "Восстановите хронологию", "text": "Таблица «дата — событие — документ»: передача площадки, документации, аванса, согласования и приостановки."}, {"@type": "HowToStep", "position": 3, "name": "Квалифицируйте причину", "text": "Вина заказчика, просрочка кредитора, непреодолимая сила или смешанная вина — от квалификации зависит норма и глубина защиты."}, {"@type": "HowToStep", "position": 4, "name": "Ответьте на претензию мотивированно", "text": "Со ссылками на ч. 9 ст. 34 закона № 44-ФЗ, п. 3 ст. 405 и ст. 406 ГК и приложением доказательств."}, {"@type": "HowToStep", "position": 5, "name": "Проверьте списание по № 783", "text": "Если контракт исполнен и неустойка в порогах 5/20 % — заказчик обязан списать долг; напомните об обязанности письменно."}, {"@type": "HowToStep", "position": 6, "name": "Защищайте обеспечение", "text": "Возражайте против удержания и зачёта спорных сумм сразу, фиксируя спорность требования."}, {"@type": "HowToStep", "position": 7, "name": "Готовьтесь к суду", "text": "Заявление о снижении по ст. 333 ГК — письменно в первой инстанции; исключение периодов — с документальной хронологией."}]}
</script>
